#include <string>
#include <cstddef>

//==========================================
// TEXT UTILITY MODULE (UTF-8 aware helpers)
// std::string counts BYTES, but a letter such as "e with accent" or an emoji takes 2 to 4
// bytes in UTF-8. Table columns and length limits must count CHARACTERS, otherwise
// the table is misaligned and a long text can be cut in the middle of a character.
// A UTF-8 continuation byte always looks like 10xxxxxx, every other byte starts a character.
//==========================================

//--- utf8IsContinuation ---------------------------------------------------------------------------
// What    : True for the 2nd, 3rd and 4th byte of a UTF-8 character (bit pattern 10xxxxxx). These
//           bytes do not start a new character.
// Returns : true for a continuation byte
// Used by : editDistance (dp.h), utf8Length, utf8Prefix
//--------------------------------------------------------------------------------------------------
bool utf8IsContinuation(unsigned char byte) {
    return (byte & 0xC0) == 0x80;
}

// number of characters (not bytes) in a UTF-8 text
//--- utf8Length -----------------------------------------------------------------------------------
// What    : Number of characters in a UTF-8 text. std::string::size() counts bytes, which breaks
//           table alignment for accents and emoji.
// Returns : the character count
// Used by : centerText (tui.h), closestTitle (store.h), fit (tui.h), fitRight (tui.h)
//--------------------------------------------------------------------------------------------------
size_t utf8Length(const std::string& s) {
    size_t count = 0;
    for (size_t i = 0; i < s.size(); i++) {
        if (!utf8IsContinuation((unsigned char)s[i])) count++;
    }
    return count;
}

// the first maxChars characters of a text, never cutting a character in the middle
//--- utf8Prefix -----------------------------------------------------------------------------------
// What    : The first N characters of a text, never cutting a character in the middle.
// Returns : the shortened text
// Used by : centerText (tui.h), fit (tui.h), fitRight (tui.h)
//--------------------------------------------------------------------------------------------------
std::string utf8Prefix(const std::string& s, size_t maxChars) {
    size_t chars = 0;
    for (size_t i = 0; i < s.size(); i++) {
        if (!utf8IsContinuation((unsigned char)s[i])) {
            if (chars == maxChars) return s.substr(0, i);
            chars++;
        }
    }
    return s;
}

#endif //STEAM_TEXTUTIL_H
